import{_ as r,o as t,c as o,a5 as a}from"./chunks/framework.DvE3tBec.js";const d=JSON.parse('{"title":"Software","description":"","frontmatter":{},"headers":[],"relativePath":"software.md","filePath":"software.md","lastUpdated":1791387718000}'),n={name:"software.md"};function i(s,e,l,p,h,c){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="software" tabindex="-1">Software <a class="header-anchor" href="#software" aria-label="Permalink to &quot;Software&quot;">​</a></h1><p>All developed software is organized within the <a href="https://github.com/open-eo/" target="_blank" rel="noreferrer">openEO GitHub organization</a>.</p><h2 id="clients" tabindex="-1">Clients <a class="header-anchor" href="#clients" aria-label="Permalink to &quot;Clients&quot;">​</a></h2><p>Software that allows remote sensers and other users to access the openEO back-ends:</p><table tabindex="0"><thead><tr><th>Client software</th><th>Package Manager / Hosted Version</th><th>GitHub</th></tr></thead><tbody><tr><td>JavaScript/TypeScript library</td><td>npm: <a href="https://www.npmjs.com/package/@openeo/js-client" target="_blank" rel="noreferrer">@openeo/js-client</a></td><td><a href="https://github.com/Open-EO/openeo-js-client" target="_blank" rel="noreferrer">openeo-js-client</a></td></tr><tr><td>Python library</td><td>PyPI: <a href="https://pypi.org/project/openeo/" target="_blank" rel="noreferrer">openeo</a> / Conda Forge: <a href="https://anaconda.org/conda-forge/openeo" target="_blank" rel="noreferrer">openeo</a></td><td><a href="https://github.com/Open-EO/openeo-python-client" target="_blank" rel="noreferrer">openeo-python-client</a></td></tr><tr><td>QGIS plugin</td><td>QGIS plugin repository: <a href="https://plugins.qgis.org/plugins/openeo_plugin/" target="_blank" rel="noreferrer">openEO</a></td><td><a href="https://github.com/Open-EO/openeo-qgis-plugin" target="_blank" rel="noreferrer">openeo-qgis-plugin</a></td></tr><tr><td>R library</td><td>CRAN: <a href="https://cran.r-project.org/package=openeo" target="_blank" rel="noreferrer">openeo</a></td><td><a href="https://github.com/Open-EO/openeo-r-client" target="_blank" rel="noreferrer">openeo-r-client</a></td></tr><tr><td>Web Editor</td><td><a href="https://editor.openeo.org" target="_blank" rel="noreferrer">Hosted Version</a></td><td><a href="https://github.com/Open-EO/openeo-web-editor" target="_blank" rel="noreferrer">openeo-web-editor</a></td></tr></tbody></table><p>See the <a href="/documentation/1.0/"><strong>getting started guide for users</strong></a> for more information. Users considering to implement a new client library should read the <a href="/documentation/1.0/developers/clients/getting-started.html"><strong>getting started guide for client developers</strong></a>.</p><h2 id="back-ends" tabindex="-1">Back-ends <a class="header-anchor" href="#back-ends" aria-label="Permalink to &quot;Back-ends&quot;">​</a></h2><p>Data and infrastructure providers can host their own instance of the openEO API:</p><ul><li><a href="https://github.com/Open-EO/openeo-geopyspark-driver" target="_blank" rel="noreferrer">GeoPySpark (Geotrellis)</a> (by VITO) - has <a href="https://github.com/Open-EO/openeo-geopyspark-integrationtests" target="_blank" rel="noreferrer">integration tests</a>, requires <a href="https://github.com/Open-EO/openeo-geotrellis-extensions" target="_blank" rel="noreferrer">GeoTrellis extensions</a>.</li><li><a href="https://github.com/Open-EO/openeo-earthengine-driver" target="_blank" rel="noreferrer">Google Earth Engine</a> (by WWU)</li><li><a href="https://github.com/Open-EO/openeo-grassgis-driver" target="_blank" rel="noreferrer">GRASS GIS</a> (by mundialis)</li><li><a href="https://github.com/Open-EO/openeo-jeodpp-driver" target="_blank" rel="noreferrer">JEODPP</a> (by JRC)</li><li><a href="https://github.com/SARScripts/openeo_odc_driver" target="_blank" rel="noreferrer">Open Data Cube</a> (by EURAC, funded by ESA)</li><li><a href="https://github.com/Open-EO/openeo-eodc-driver" target="_blank" rel="noreferrer">Apache Airflow / eoDataReaders</a> (by EODC)</li><li><a href="https://github.com/Open-EO/openeo-sentinelhub-python-driver" target="_blank" rel="noreferrer">Sentinel Hub</a> (by Sinergise)</li><li><a href="https://github.com/Open-EO/openeo-wcps-driver" target="_blank" rel="noreferrer">WCPS (rasdaman)</a> (by EURAC)</li><li><a href="https://github.com/Open-EO/openeo-r-backend" target="_blank" rel="noreferrer">R back-end</a> (by WWU) - discontinued until further notice (last version: 0.3)</li><li><a href="https://github.com/IBM/tensorlakehouse-openeo-driver" target="_blank" rel="noreferrer">TensorLakeHouse</a> (by IBM Research)</li></ul><p>See the <a href="/documentation/1.0/developers/backends/getting-started.html"><strong>getting started guide for back-end providers</strong></a> for more information.</p><p>To start developing a new back-end driver, you may start with any of the common functionalities implemented in several programming languages:</p><ul><li><a href="https://github.com/Open-EO/openeo-spring-driver" target="_blank" rel="noreferrer">Java (Spring) API Commons</a></li><li><a href="https://github.com/Open-EO/openeo-python-driver" target="_blank" rel="noreferrer">Python API Commons</a></li><li><a href="https://github.com/Open-EO/openeo-pg-parser-python" target="_blank" rel="noreferrer">Python Process Graph Parser</a></li><li><a href="https://github.com/Open-EO/openeo-js-processgraphs" target="_blank" rel="noreferrer">JavaScript Process Graph Parser</a></li><li><a href="https://github.com/Open-EO/openeo-processes-dask" target="_blank" rel="noreferrer">Python Processes</a> - many openEO processes implemented in Python</li></ul><p>Our approach to tackle language-agnostic user-defined functions can be found in the following repositories:</p><ul><li><a href="https://github.com/Open-EO/openeo-udf" target="_blank" rel="noreferrer">UDF Python reference implementation</a></li><li><a href="https://github.com/Open-EO/openeo-r-udf" target="_blank" rel="noreferrer">UDF R reference implementation</a></li></ul><h2 id="specification" tabindex="-1">Specification <a class="header-anchor" href="#specification" aria-label="Permalink to &quot;Specification&quot;">​</a></h2><p>The API specification is available in the <strong><a href="https://github.com/Open-EO/openeo-api" target="_blank" rel="noreferrer">openEO API repository</a></strong>. The process definitions are available in the <strong><a href="https://github.com/Open-EO/openeo-processes" target="_blank" rel="noreferrer">openEO processes repository</a></strong>.</p><h2 id="ecosystem" tabindex="-1">Ecosystem <a class="header-anchor" href="#ecosystem" aria-label="Permalink to &quot;Ecosystem&quot;">​</a></h2><ul><li><a href="https://github.com/Open-EO/openeo-test-suite" target="_blank" rel="noreferrer">Common Test Suite</a> - Validation for back-end implementations.</li><li><a href="https://hub.openeo.org" target="_blank" rel="noreferrer">openEO Hub</a> (<a href="https://github.com/Open-EO/openeo-hub" target="_blank" rel="noreferrer">GitHub</a>) - The central platform for openEO services.</li><li><a href="https://github.com/Open-EO/openeo-processes-docgen" target="_blank" rel="noreferrer">Processes DocGen</a> - A tool to generate a visual interface for openEO process definitions.</li><li><a href="https://github.com/Open-EO/openeo-vue-components" target="_blank" rel="noreferrer">Vue.js Components</a> - Common Vue.js 2 components for openEO</li><li><a href="https://github.com/Open-EO/openeo-js-commons" target="_blank" rel="noreferrer">JavaScript Commons</a> - Common JavaScript functionality for openEO clients and back-ends</li></ul>',18)])])}const f=r(n,[["render",i]]);export{d as __pageData,f as default};
